'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { updateProfile } from '../../services/api';
import Modal from '../../components/ui/Modal';
import { User, Mail, Phone, ArrowLeft, Save } from 'lucide-react';

export default function ProfilePage() {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [modal, setModal] = useState({ isOpen: false, title: '', message: '' });

    const [formData, setFormData] = useState({
        name: '',
        email: '',
        gender: 'Male', // Default, or fetch from user
        phone: ''
    });

    const [userId, setUserId] = useState(null);

    useEffect(() => {
        // Load initial data from local storage or fetch from API if we had a getUser endpoint
        // For now, relies on local storage for phone/name updates
        const uid = localStorage.getItem('disc_user_id');
        const storedName = localStorage.getItem('disc_user_name') || '';
        const storedPhone = localStorage.getItem('disc_user_phone') || '';
        // Ideally we fetch full profile here.
        // But since we can only update, let's just prefill what we have.

        if (uid) setUserId(uid);
        setFormData(prev => ({
            ...prev,
            name: storedName,
            phone: storedPhone
        }));

        // Fetch latest profile logic could be added here
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            if (!userId) throw new Error("User ID missing");

            const result = await updateProfile(userId, {
                name: formData.name,
                email: formData.email,
                gender: formData.gender
            });

            // Update local storage
            localStorage.setItem('disc_user_name', result.name);

            setModal({
                isOpen: true,
                title: 'Profile Updated',
                message: 'Your profile details have been saved successfully.'
            });
        } catch (error) {
            console.error("Update failed", error);
            setModal({
                isOpen: true,
                title: 'Error',
                message: 'Failed to update profile. Please try again.'
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <main className="min-h-screen flex flex-col items-center justify-center p-4 bg-black relative">
            <Modal
                isOpen={modal.isOpen}
                onClose={() => setModal({ ...modal, isOpen: false })}
                title={modal.title}
                message={modal.message}
            />

            {/* Background Ambience */}
            <div className="fixed inset-0 z-0 pointer-events-none">
                <div className="absolute top-0 w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-zinc-900/50 via-black to-black" />
            </div>

            <div className="z-10 w-full max-w-2xl">
                <button
                    onClick={() => router.back()}
                    className="mb-8 flex items-center gap-2 text-zinc-400 hover:text-white transition-colors"
                >
                    <ArrowLeft size={20} />
                    <span>Back to Dashboard</span>
                </button>

                <div className="glass-panel p-8 md:p-12 rounded-3xl border border-white/10 bg-zinc-900/60">
                    <h1 className="text-3xl font-light text-white mb-8 border-b border-white/10 pb-4">
                        Edit Profile
                    </h1>

                    <form onSubmit={handleSubmit} className="space-y-6">
                        {/* Phone (Read Only) */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Mobile Number</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600">
                                    <Phone size={18} />
                                </span>
                                <input
                                    type="text"
                                    name="phone"
                                    value={formData.phone}
                                    readOnly
                                    className="w-full bg-black/30 border border-white/5 rounded-xl px-12 py-3 text-zinc-500 cursor-not-allowed"
                                />
                            </div>
                        </div>

                        {/* Name */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Full Name</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500">
                                    <User size={18} />
                                </span>
                                <input
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    placeholder="John Doe"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl px-12 py-3 text-white focus:border-cyan-500/50 focus:outline-none focus:ring-1 focus:ring-cyan-500/50 transition-all"
                                />
                            </div>
                        </div>

                        {/* Email */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Email Address</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500">
                                    <Mail size={18} />
                                </span>
                                <input
                                    type="email"
                                    name="email"
                                    value={formData.email}
                                    onChange={handleChange}
                                    placeholder="john@example.com"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl px-12 py-3 text-white focus:border-cyan-500/50 focus:outline-none focus:ring-1 focus:ring-cyan-500/50 transition-all"
                                />
                            </div>
                        </div>

                        {/* Gender */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Gender</label>
                            <div className="grid grid-cols-3 gap-4">
                                {['Male', 'Female', 'Other'].map((option) => (
                                    <button
                                        key={option}
                                        type="button"
                                        onClick={() => setFormData(prev => ({ ...prev, gender: option }))}
                                        className={`py-3 rounded-xl border transition-all ${formData.gender === option
                                            ? 'bg-white text-black border-white font-medium'
                                            : 'bg-transparent text-zinc-500 border-white/10 hover:border-white/30'
                                            }`}
                                    >
                                        {option}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full mt-8 bg-gradient-to-r from-cyan-600 to-blue-600 text-white font-bold text-lg py-4 rounded-xl hover:scale-[1.02] transition-transform shadow-[0_0_20px_rgba(34,211,238,0.3)] flex items-center justify-center gap-2"
                        >
                            <Save size={20} />
                            {loading ? 'Saving...' : 'Save Changes'}
                        </button>
                    </form>
                </div>
            </div>
        </main>
    );
}
